# One-off (13 Nov 2026): the Epilogue of the expanded book: conclusion on the arc, the claims table in the new chapter order
# (rows of the draft kept word for word, chapter column and numbers as placeholders), open problems, and the hand-off.
import re, os
H = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
s = open(os.path.join(H, 'tools', 'old', 'epilogue-old.html'), encoding='utf8').read()
rows = [(m.group(1), m.group(2), m.group(3)) for m in re.finditer(r'<tr><td>(\d+)</td><td>(.*?)</td><td>(.*?)</td></tr>', s)]
KEY = {'1': 'three', '2': 'slider', '3': 'bonds', '4': 'rd', '5': 'scut3', '6': 'web', '7': 'centre2', '8': 'rosettes', '9': 'walls', '10': 'web', '11': 'everyn', '12': 'golden', '13': 'bells', '14': 'family'}
FIXST = {'proved (2.2 in #48, #105, #93)': 'proved ({{s:o2.2}} in #48, #105, #93)', 'proved; 4.3 exact': 'proved; {{s:o4.3}} exact',
         'proved (#104); 7.3 and 7.4 confirmed by sweeps': 'proved (#104); {{s:o7.3}} and {{s:o7.4}} confirmed by sweeps', 'proved (11.1 in #105); checked n ≤ 9 and n ≤ 7': 'proved ({{s:o11.1}} in #105); checked n ≤ 9 and n ≤ 7'}
order = ['three', 'kelvin', 'slider', 'bonds', 'rd', 'scut3', 'web', 'centre1', 'centre2', 'rosettes', 'walls', 'everyn', 'golden', 'family', 'bells']
R = {k: [] for k in order}
for c, claim, st in rows:
    k = KEY[c]; st = FIXST.get(st, st)
    if 'Proposition {{s:o5.1}}' in claim: k = 'centre1'
    if claim.startswith('Theorems {{s:o7.1}}'):
        R['centre1'].append(('Theorem {{s:o7.1}}: a generic sweep of a simple 4-polytope is a scutoid tissue, births, swaps and deaths counted by h<sub>1</sub>, h<sub>2</sub>, h<sub>3</sub>; for the 4D permutohedron 26, 66, 26', 'proved (#104)'))
        claim = claim.replace('Theorems {{s:o7.1}}, {{s:o7.1}}′: sweeps of simple polytopes counted by the h-vector;', 'Theorem {{s:o7.1}}′: sweeps in every dimension counted by the h-vector;')
    R[k].append((claim, st))
R['kelvin'] += [('Proposition {{s:kelvin36}}: the 36 edges of Kelvin\'s cell are 12 swaps of each pair; its squares and hexagons are the two rules among swaps', 'proved (classical, read as swaps)'),
                ('Kelvin\'s cell is the only lone tiler of the cube–octahedron sweep besides the cube (#100); it is the fixed point of the pair swap μ ↔ 3 − μ, where the Dehn coefficient, odd under the swap, vanishes and the wall area is largest', 'proved (#100; swaps study K3, K4, exact)')]
R['slider'].append(('Theorem {{s:silent}}: on the slider the fourth harmonic vanishes only at the golden stop, Icosaxes, which is silent in degrees 2, 4, 8, 14 (#94)', 'proved (#94)'))
R['centre1'].append(('The scutoid swap is the one self-reverse event of a 4D sweep; a self-reverse class exists only in even dimension, and the pure swap (one contact lost, one made at a corner) only in four', 'proved (from Theorems {{s:o7.1}}, {{s:o7.1}}′; swaps study K8, exact for d ≤ 7)'))
R['walls'].append(('Proposition {{s:cones}}: the chamber map of the Swap Rule is an affine section of a secondary fan, so its walls are straight', 'proved (a reading)'))
R['family'] += [('The sections of the tesseract across a long diagonal (#89) are permutohedra of four values with a repeated value, (0, h, 1, 1) for 0 &lt; h &lt; 1', 'exact (checked against #89\'s data: check89.py)'),
                ('Sliding a member along a swap direction keeps it in the family (#49 read as a Minkowski sum); #50\'s five are parallelohedra, hence of Fedorov\'s five types; the name-by-name match is open', 'proved (classical); match open')]
table = '<table class="claims">\n<tr><th>ch.</th><th>claim</th><th>status</th></tr>\n' + ''.join(f'<tr><td>{{{{ch:{k}}}}}</td><td>{c}</td><td>{st}</td></tr>\n' for k in order for c, st in R[k]) + '</table>'
i = s.index('<h2>Open problems'); j = s.index('</p>', i) + 4; opens = s[i:j]
opens = opens.replace('(Chapter {{ch:o8}})', '(Chapter {{ch:rosettes}})').replace('(Chapter {{ch:o9}})', '(Chapter {{ch:walls}})').replace('(Chapter {{ch:o12}})', '(Chapter {{ch:golden}})').replace('(Chapters {{ch:o6}} and {{ch:o10}})', '(Chapter {{ch:web}})').replace('(Chapter {{ch:o14}})', '(Chapter {{ch:family}})')
opens = opens.replace('</p>', ' (6) The 4D Vacuus of the hop, the move that does not undo itself, has no sophisticated centre (studies/2026-11-12-hop-4d-vacuus, a negative answer); does any other move of DICTO\'s lines give the 4D permutohedron\'s kind of heart? (7) Match #50\'s five space-fillers with Fedorov\'s five of Proposition {{s:o14.4}}, name by name.</p>')
legend = s[s.index('<h2>The main claims'):s.index('<table class="claims">')]
out = '''<h1 class="chapter" id="epilogue">Epilogue. What has been shown</h1>
<h2>Conclusion</h2>
<p>The book followed one move, two neighbouring values changing places, from a hexagon to a family and back to the bells. At the beginning the swap built solids: the truncated triangle is the permutohedron of three values and every face of every permutohedron is a truncated triangle or a rectangle (Chapter {{ch:three}}); Kelvin's cell is the 24 orders of four values, its 36 edges the swaps of three pairs, and it fills space alone at the fixed point of its line's pair swap (Chapter {{ch:kelvin}}); the golden loop of DICTONIC is exactly the set of four-value permutohedra with the cube's full symmetry, each filling space with its reciprocal in one way only, and its golden stop alone is silent in the fourth harmonic (Chapter {{ch:slider}}); the weight that drives the web of bonds is the spacing of the four values, d = (g − m)/(g + m) (Chapter {{ch:bonds}}). The paradigm also showed where it stops: DICTO's rhombic dodecahedron taken apart closes into the chamfered cube, whose edges are no swaps (Chapter {{ch:rd}}).</p>
<p>At the centre the swap moved inside cells. Scutoids are swaps seen in a slice (Chapter {{ch:scut3}}). The permutohedron of five values is the web of swaps; its Vacuus has 65 central slices of four kinds, with five DICTO 1:2 Truncated Octahedra at its heart, and the Mirror Law tells which faces lie on mirrors (Chapter {{ch:web}}). Swept, it is a scutoid tissue of 26 births, 66 swaps and 26 deaths, the swaps the one event that is its own reverse (Chapter {{ch:centre1}}); every simple 4-polytope sweeps the same way, by its h-vector, and between the Queens the swaps balance, 601 each way (Chapter {{ch:centre2}}). The Coxeter chain tells clean tissues from rosettes, which balance with symmetry and fail without it (Chapter {{ch:rosettes}}), and the walls of the Swap Rule of close packing are swaps one dimension up (Chapter {{ch:walls}}). Part Three carried the counts into every dimension (Chapter {{ch:everyn}}) and cut the 4D filling in the golden direction into a filling of 35 kinds of cell, non-periodic in one direction only (Chapter {{ch:golden}}). At the summit the walls moved instead of the values: the permutohedron's family runs from Kelvin's cell to the associahedron, every edge a swap, and in three dimensions its members that fill space by sliding are exactly Fedorov's five (Chapter {{ch:family}}). The return found the permutohedron in the oldest walk through all the orders of a set, English change ringing, where the plain hunt is the only shortest way from rounds to backrounds for every number of bells (Chapter {{ch:bells}}).</p>
<p><b>Where the swap carries a law.</b> The study of swaps across DICTO's work (studies/2026-11-13-swaps-and-fixed-points) found that a law sits at the fixed point of a swap only where the swap forces it, and kept its classes exact; this book uses them as found. The scutoid swap is the self-reverse event of a sweep, counted by h<sub>2</sub>: a law at a fixed point (Chapter {{ch:centre1}}). Kelvin's cell is the fixed point of its line's pair swap, where an odd quantity, the Dehn coefficient, must vanish (Chapter {{ch:kelvin}}). The balance law is an invariance, not a fixed point: the same count each way, and false without symmetry (Chapters {{ch:centre2}} and {{ch:rosettes}}). The Mirror Law sits on the mirrors, the fixed places of the reflections (Chapter {{ch:web}}). The two halves of the plain hunt are a swapped pair (Chapter {{ch:bells}}). The Vacuus counts and the family theorem involve no swap at a fixed point, and the silent golden station is not at one (Chapter {{ch:slider}}).</p>
<p><b>Onward.</b> The swaps of this book are swaps of neighbours: values, cells, layers. The series follows the others in their home books. Faces with corners, the polar swap behind DICTO's faces-not-corners view, and the canonical form of the associahedron belong to Book Eleven, <i>A Brief Geometry of Space</i>; the Galois swap √5 ↔ −√5 to Book Nine, <i>The Golden Ladder</i>, and Book Eleven; the turn μ ↔ c/μ, which folds every polar line about the solid whose faces all touch one sphere, to Book Eleven; the layers c ↔ h to Book Six, <i>HexOct</i>; the mirrors of the five solids to Book Eight, <i>The Platonic Solids</i>. The question of the series stays open, and this book hands it on: what stays in place when the parts of space change places?</p>
''' + opens + '\n' + legend + table + '\n'
open(os.path.join(H, 'epilogue.html'), 'w', encoding='utf8').write(out); print('rows', sum(len(v) for v in R.values()))
